  entities: [Task]
}

// Intentionally declared with only the Project entity so that Wasp's
// automatic, entity-based cache invalidation does NOT refresh it when a
// Task action runs. The client keeps it up to date manually.
query getProjectStats {
  fn: import { getProjectStats } from "@src/queries.js",
  entities: [Project]
}

action addTask {
  fn: import { addTask } from "@src/actions.js",
  entities: [Task]
}

action toggleTask {
  fn: import { toggleTask } from "@src/actions.js",
  entities: [Task]
}

// Returns every task with its id, title, done state and project id.
// Declared with the Task entity in main.wasp, so Wasp automatically
// invalidates this Query whenever an Action that shares the Task entity
// (addTask / toggleTask) runs.
export const getTasks = async (_args, context) => {
  return context.entities.Task.findMany({
    select: {
      id: true,
      title: true,
      done: true,
      projectId: true,
    },
  })
}

// Derived/computed aggregate: for every project, returns its id, name, the
// total number of tasks and the number of done tasks.
//
// This Query is intentionally declared with only the Project entity (see
// main.wasp). Because it depends on Task data only through a Prisma relation
// (not through a declared entity), Wasp's automatic invalidation will NOT
// refresh it when addTask / toggleTask run. The client must invalidate it
// manually after those Actions.
export const getProjectStats = async (_args, context) => {
  const projects = await context.entities.Project.findMany({
    include: {
      tasks: {
        select: { done: true },
      },
    },
  })
  return projects.map((project) => ({
    id: project.id,
    name: project.name,
    total: project.tasks.length,
    done: project.tasks.filter((task) => task.done).length,
  }))
}

// Creates a new task in the given project.
// Shares the Task entity with getTasks, so Wasp automatically refreshes
// getTasks after this Action runs.
export const addTask = async ({ projectId, title }, context) => {
  return context.entities.Task.create({
    data: {
      title,
      projectId,
    },
  })
}

// Flips a task's done state.
// Shares the Task entity with getTasks, so Wasp automatically refreshes
// getTasks after this Action runs.
export const toggleTask = async ({ taskId }, context) => {
  const task = await context.entities.Task.findUnique({
    where: { id: taskId },
  })
  if (!task) {
    throw new Error(`Task with id ${taskId} not found`)
  }
  return context.entities.Task.update({
    where: { id: taskId },
    data: { done: !task.done },
  })
}

// Database seed named `devSeed` (declared in main.wasp under app.db.seeds).
//
// It is safe to run repeatedly: it clears any existing tasks and projects
// first, then recreates the deterministic initial board state:
//   - Project "Work" with tasks "Ship release" (done) and "Write docs" (not done)
//   - Project "Home" with task "Buy groceries" (not done)
export const devSeed = async (prisma) => {
  // Delete tasks first to respect the foreign key relation.
  await prisma.task.deleteMany({})
  await prisma.project.deleteMany({})

  await prisma.project.create({
    data: {
      name: 'Work',
      tasks: {
        create: [
          { title: 'Ship release', done: true },
          { title: 'Write docs', done: false },
        ],
      },
    },
  })

  await prisma.project.create({
    data: {
      name: 'Home',
      tasks: {
        create: [{ title: 'Buy groceries', done: false }],
      },
    },
  })
}

import { useQuery, useAction } from 'wasp/client/operations'
import { getTasks, getProjectStats, addTask, toggleTask } from 'wasp/client/operations'
import { useQueryClient } from '@tanstack/react-query'
import './Main.css'

export const MainPage = () => {
  const tasksQuery = useQuery(getTasks)
  const statsQuery = useQuery(getProjectStats)

  const queryClient = useQueryClient()

  // getTasks shares the Task entity with addTask/toggleTask, so Wasp refreshes
  // it automatically. getProjectStats is only declared with the Project entity,
  // so we invalidate it manually here after each Task action runs.
  const invalidateStats = () => {
    queryClient.invalidateQueries(getProjectStats.queryCacheKey)
  }

  const addTaskAction = useAction(addTask)
  const toggleTaskAction = useAction(toggleTask)

  const handleAddTask = async (projectId) => {
    // The new task's title may be any non-empty string.
    const title = `New task ${Date.now()}`
    await addTaskAction({ projectId, title })
    invalidateStats()
  }

  const handleToggleTask = async (taskId) => {
    await toggleTaskAction({ taskId })
    invalidateStats()
  }

  return (
    <div className="container">
      <main>
        <h2 className="welcome-title">Task Board</h2>

        <section>
          <h3>Projects</h3>
          {statsQuery.isLoading && <p>Loading stats…</p>}
          {statsQuery.error && <p>Error loading stats.</p>}
          <ul style={{ listStyle: 'none', padding: 0 }}>
            {statsQuery.data?.map((stat) => (
              <li key={stat.id} style={{ marginBottom: '0.5rem' }}>
                <strong>{stat.name}</strong>{' '}
                <span data-testid={`stat-total-${stat.id}`}>{stat.total}</span>{' '}
                <span>done:</span>{' '}
                <span data-testid={`stat-done-${stat.id}`}>{stat.done}</span>{' '}
                <button
                  type="button"
                  data-testid={`add-task-${stat.id}`}
                  onClick={() => handleAddTask(stat.id)}
                >
                  Add task
                </button>
              </li>
            ))}
          </ul>
        </section>

        <section>
          <h3>Tasks</h3>
          {tasksQuery.isLoading && <p>Loading tasks…</p>}
          {tasksQuery.error && <p>Error loading tasks.</p>}
          <ul style={{ listStyle: 'none', padding: 0 }}>
            {tasksQuery.data?.map((task) => (
              <li key={task.id} style={{ marginBottom: '0.25rem' }}>
                <span data-testid={`task-${task.id}`}>
                  {task.done ? '✅' : '⬜'} {task.title} (project {task.projectId})
                </span>{' '}
                <button
                  type="button"
                  data-testid={`toggle-${task.id}`}
                  onClick={() => handleToggleTask(task.id)}
                >
                  Toggle
                </button>
              </li>
            ))}
          </ul>
        </section>
      </main>
    </div>
  )
}

